-- The Close pack (docs/plan.md §1.232, Wave Y item Y3): a month's close per client and accounting
-- connection (`close_period`), its checklist (`close_item`), and the journal entries proposed for it
-- (`close_entry`, `close_entry_line`: accruals, their reversals, recurring journals), each written to
-- the client's accounting tool only through an external action after approval. New tables only, so
-- the previous Worker keeps working. Generated by drizzle-kit from
-- packs/bookkeeping/src/close/schema.ts and renumbered 0090 (0086-0089 are other items); the grants,
-- history triggers, the sign-off freeze, row-level security and pack comments at the end are
-- hand-written.
CREATE TABLE "close_entry" (
	"id" uuid PRIMARY KEY DEFAULT uuid_generate_v7() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"period_id" uuid NOT NULL,
	"kind" text NOT NULL,
	"entry_key" text NOT NULL,
	"status" text DEFAULT 'proposed' NOT NULL,
	"proposed_by" text NOT NULL,
	"txn_date" date NOT NULL,
	"reverse_on" date,
	"amount" numeric(14, 4) NOT NULL,
	"currency" text DEFAULT 'USD' NOT NULL,
	"memo" text NOT NULL,
	"reason" text,
	"from_entry_id" uuid,
	"sources" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"agent_version_id" uuid,
	"run_id" uuid,
	"user_id" uuid,
	"external_action_id" uuid,
	"qbo_id" text,
	"error" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"decided_at" timestamp with time zone,
	"posted_at" timestamp with time zone,
	CONSTRAINT "close_entry_id_tenant_key" UNIQUE("id","tenant_id"),
	CONSTRAINT "close_entry_kind_check" CHECK ("close_entry"."kind" in ('accrual', 'reversal', 'recurring')),
	CONSTRAINT "close_entry_status_check" CHECK ("close_entry"."status" in ('proposed', 'rejected', 'posted', 'failed', 'superseded')),
	CONSTRAINT "close_entry_proposed_by_check" CHECK ("close_entry"."proposed_by" in ('pattern', 'repeat', 'model', 'person')),
	CONSTRAINT "close_entry_amount_check" CHECK ("close_entry"."amount" > 0),
	CONSTRAINT "close_entry_memo_check" CHECK (length("close_entry"."memo") between 1 and 400),
	CONSTRAINT "close_entry_posted_check" CHECK ("close_entry"."status" <> 'posted' or "close_entry"."qbo_id" is not null),
	CONSTRAINT "close_entry_reversal_check" CHECK ("close_entry"."kind" <> 'reversal' or "close_entry"."from_entry_id" is not null),
	CONSTRAINT "close_entry_proposer_check" CHECK ("close_entry"."proposed_by" = 'person' and "close_entry"."user_id" is not null or "close_entry"."proposed_by" <> 'person' and "close_entry"."agent_version_id" is not null),
	CONSTRAINT "close_entry_sources_check" CHECK ("close_entry"."proposed_by" <> 'model' or jsonb_array_length("close_entry"."sources") > 0)
);
