-- Nothing is deleted. A period's status, sign-off and last check change; a line's findings change
-- as it is checked again, and a person may waive it; an entry's status columns change as it is
-- decided and written; an entry's lines never change.
GRANT SELECT, INSERT, UPDATE ON close_period, close_item, close_entry TO cs_runtime;
