-- A signed-off period never changes: not the period, not its checklist, not its entries, and nothing
-- is added to it. Checked under the caller's row-level security, which already holds the period.
CREATE OR REPLACE FUNCTION close_forbid_after_sign_off() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_TABLE_NAME = 'close_period' THEN
    IF OLD.status = 'signed_off' THEN
      RAISE EXCEPTION 'a signed-off close never changes' USING ERRCODE = 'restrict_violation';
    END IF;
  ELSIF EXISTS (
    SELECT 1 FROM close_period p
    WHERE p.id = NEW.period_id AND p.tenant_id = NEW.tenant_id AND p.status = 'signed_off'
  ) THEN
    RAISE EXCEPTION 'a signed-off close never changes' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END
$$;
--> statement-breakpoint
CREATE TRIGGER close_period_frozen BEFORE UPDATE ON close_period
  FOR EACH ROW EXECUTE FUNCTION close_forbid_after_sign_off();
--> statement-breakpoint
CREATE TRIGGER close_item_frozen BEFORE INSERT OR UPDATE ON close_item
  FOR EACH ROW EXECUTE FUNCTION close_forbid_after_sign_off();
--> statement-breakpoint
CREATE TRIGGER close_entry_frozen BEFORE INSERT OR UPDATE ON close_entry
  FOR EACH ROW EXECUTE FUNCTION close_forbid_after_sign_off();
--> statement-breakpoint
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['close_period', 'close_item', 'close_entry', 'close_entry_line'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY tenant_isolation ON %I FOR ALL TO PUBLIC '
      'USING (tenant_id = any(app_tenant_ids())) '
      'WITH CHECK (tenant_id = any(app_tenant_ids()))', t);
    EXECUTE format('COMMENT ON TABLE %I IS %L', t, 'pack:close');
  END LOOP;
END
$$;
